/* AIOps, Incident & Change, Observability */
(function () {
  const { h, raw, ui, chart, data: D } = COC, { STAFF, ALL } = COC.roleSets;

  /* ================= AIOPS ================= */
  const AI = { rb: null };
  COC.actions['ai.exec'] = a => { const [rb, ctx] = a.split('@'); const r = D.runbooks.find(x => x.id === rb); COC.toast('▶ Running ' + r.id + ' – ' + r.name + '…'); setTimeout(() => { COC.audit('Runbook executed: ' + r.id, ctx); COC.toast('✔ ' + r.name + ' completed on ' + ctx, 'ok'); }, 1100); };
  COC.actions['ai.fix'] = id => { const p = D.predict.find(x => x.id === id); p.done = true; COC.audit('Predictive remediation applied', p.fix + ' @ ' + p.res); COC.toast('Applied: ' + p.fix, 'ok'); COC.refresh(); };
  COC.actions['ai.ack'] = () => { const open = D.incidents.find(i => i.id === D.storm.incident); if (!open) { D.incidents.unshift({ id: D.storm.incident, title: D.storm.root, sev: 'critical', stage: 1, tenant: 'Acme Bank', owner: 'jayant', ext: 'SNOW-48211', notes: [] }); } AI.opened = true; COC.audit('Correlated incident opened', D.storm.incident); COC.toast(D.storm.incident + ' opened (47 alerts → 1 incident)', 'ok'); COC.refresh(); };
  COC.register({ id: 'aiops', name: 'AIOps / Intelligent Ops', icon: '🧠', phase: 4, roles: STAFF, render() {
    const t = COC.tabs.aiops || 'anom', a = D.aiSeries;
    let body;
    if (t === 'anom') body = h`<div class="card"><h2>Learned baseline vs observed – payments-api latency (ms, 48h)</h2>${chart.line([{ name: 'Observed', color: 'var(--acc)', data: a.obs }, { name: 'Learned baseline', color: 'var(--mut)', dash: 1, data: a.base }], { labels: a.labels, band: { lo: a.lo, hi: a.hi }, marks: a.marks, fmt: v => v, min: 0, max: 120, title: 'anomaly detection' })}<p class="mut">Shaded band = expected range (seasonality-aware). Red dots = deviations the model flagged: <b>3 anomalies</b>. No static threshold needed.</p></div>`;
    else if (t === 'rca') body = h`<div class="grid g21"><div class="card"><h2>Alert storm → one incident</h2><div class="row" style="gap:20px"><div class="kpi"><div class="v bad">${D.storm.raw}</div><div class="l">raw alerts</div></div><div style="font-size:28px">→</div><div class="kpi"><div class="v good">1</div><div class="l">${D.storm.incident}</div></div></div><h3 style="margin-top:14px">Root cause (confidence 91%)</h3><p><b>${D.storm.root}</b></p>${ui.table([{ h: 'Time', f: e => e[0] }, { h: 'Cloud', f: e => e[1] }, { h: 'Event', f: e => e[2] }, { h: '', f: e => e[3] ? ui.badge('ROOT', 'bad') : ui.badge('symptom', 'mut') }], D.storm.events)}<div style="margin-top:10px">${AI.opened || D.incidents.some(i => i.id === D.storm.incident) ? ui.badge('Incident opened', 'ok') : h`<button class="btn p" data-act="ai.ack" data-w>Open correlated incident</button>`}</div></div>
      <div class="card"><h2>Suggested remediation</h2>${ui.table([{ h: 'Runbook', f: r => r.name }, { h: '', f: r => ui.btn('Execute', 'ai.exec', r.id + '@eu-west-1', { s: 1, p: 1, w: 1 }) }], D.runbooks.filter(r => ['RB-05', 'RB-01'].includes(r.id)))}</div></div>`;
    else if (t === 'pred') body = h`<div class="card flat">${ui.table([{ h: 'Prediction', f: p => p.text }, { h: 'Confidence', num: 1, f: p => ui.badge(p.conf + '%', p.conf > 90 ? 'bad' : 'warn') }, { h: 'ETA', num: 1, f: p => p.eta < 24 ? p.eta + 'h' : Math.round(p.eta / 24) + 'd' }, { h: 'Suggested fix', f: p => p.fix }, { h: '', f: p => p.done ? ui.badge('applied', 'ok') : ui.btn('Apply fix', 'ai.fix', p.id, { s: 1, p: 1, w: 1 }) }], D.predict)}</div>`;
    else body = h`<div class="card flat">${ui.table([{ h: 'Runbook', f: r => r.id + ' · ' + r.name }, { h: 'Type', f: r => ui.badge(r.tag) }, { h: 'Est. time', num: 1, f: r => r.mins + ' min' }, { h: '', f: r => ui.btn('Execute', 'ai.exec', r.id + '@manual', { s: 1, p: 1, w: 1 }) }], D.runbooks)}</div>`;
    return h`<div class="ph"><div class="grow"><h1>AIOps / Intelligent Ops</h1><p class="sub">ML anomaly detection, root-cause analysis, predictive alerting, incident correlation and runbook-driven remediation.</p></div></div>
      ${ui.tabs('aiops', [['anom', 'Anomaly detection'], ['rca', 'RCA & correlation'], ['pred', 'Predictive alerts'], ['rb', 'Runbook catalog']], t)}${body}`;
  } });

  /* ================= INCIDENT & CHANGE ================= */
  COC.actions['in.adv'] = id => { const i = D.incidents.find(x => x.id === id); if (i.stage >= 3) return; i.stage++; if (i.stage === 1 && i.owner === '—') i.owner = 'jayant'; if (i.stage === 1) i.ext = i.ext || 'SNOW-' + (10000 + Math.floor(Math.random() * 80000)); COC.audit('Incident → ' + D.stages[i.stage], id); COC.toast(id + ' → ' + D.stages[i.stage], 'ok'); COC.refresh(); };
  COC.actions['in.new'] = () => COC.modal({ title: 'Open incident', body: h`<label class="f">Title<input id="i-t"></label><label class="f">Severity${ui.select('i-s', ['critical', 'high', 'medium', 'low'], 'medium', 'noop')}</label>`, actions: [{ label: 'Cancel' }, { label: 'Open', primary: true, fn: () => { const t = COC.v('i-t').trim(); if (!t) { COC.toast('Title required', 'bad'); return false; } const id = 'INC-' + (2060 + D.incidents.length); D.incidents.unshift({ id, title: t, sev: COC.v('i-s'), stage: 0, tenant: COC.state.tenant === COC.TENANTS[0] ? 'IBM Internal' : COC.state.tenant, owner: '—', ext: '', notes: [] }); COC.audit('Incident opened', id); COC.refresh(); } }] });
  COC.actions['ch.dec'] = a => { const [id, d] = a.split(':'); const c = D.changes.find(x => x.id === id); c.status = d; if (d === 'approved') c.gates.cab = true; COC.audit('Change ' + d, id); COC.toast(id + ' ' + d, d === 'approved' ? 'ok' : 'warn'); COC.refresh(); };
  COC.actions['ch.new'] = () => COC.modal({ title: 'Change request', body: h`<label class="f">What will change?<input id="c-t"></label><div class="grid g2" style="margin:0"><label class="f">Risk${ui.select('c-r', ['low', 'medium', 'high'], 'medium', 'noop')}</label><label class="f">Day of month<input id="c-d" type="number" min="1" max="30" value="20"></label></div>`, actions: [{ label: 'Cancel' }, { label: 'Submit for approval', primary: true, fn: () => { const t = COC.v('c-t').trim(); if (!t) { COC.toast('Describe the change', 'bad'); return false; } const id = 'CHG-' + (132 + D.changes.length - 7); D.changes.push({ id, title: t, target: '—', risk: COC.v('c-r'), status: 'pending', day: Math.min(30, Math.max(1, +COC.v('c-d'))), tenant: COC.state.tenant === COC.TENANTS[0] ? 'IBM Internal' : COC.state.tenant, gates: { peer: false, policy: true, cab: false } }); COC.audit('Change requested', id); COC.refresh(); } }] });
  COC.actions['in.int'] = a => { const [n, on] = a.split('|'); D.integrations.find(x => x.name === n).on = on === 'true'; COC.audit('Integration toggled', n); COC.refresh(); };
  COC.register({ id: 'incidents', name: 'Incident & Change Mgmt', icon: '🔄', phase: 4, roles: ALL, render() {
    const t = COC.tabs.incidents || 'inc', inc = COC.byTenant(D.incidents), chg = COC.byTenant(D.changes);
    let body;
    if (t === 'inc') body = h`<div class="row" style="margin-bottom:10px"><button class="btn p" data-act="in.new" data-w>＋ Open incident</button></div>${inc.map(i => h`<div class="card"><div class="row"><b>${i.id}</b> ${ui.sev(i.sev)} <span>${i.title}</span><span class="sp" style="flex:1"></span>${i.ext ? ui.badge(i.ext, 'info') : ''}<span class="mut">${i.tenant} · owner ${i.owner}</span></div><div class="stepper">${D.stages.map((s, k) => h`<div class="st ${k < i.stage ? 'done' : k === i.stage ? 'cur' : ''}">${s}</div>`)}</div>${i.stage < 3 ? ui.btn('Advance → ' + D.stages[i.stage + 1], 'in.adv', i.id, { s: 1, p: 1, w: 1 }) : ui.badge('closed with post-mortem', 'ok')}</div>`)}${inc.length ? '' : h`<div class="card empty">No incidents.</div>`}`;
    else if (t === 'chg') body = h`<div class="row" style="margin-bottom:10px"><button class="btn p" data-act="ch.new" data-w>＋ Change request</button></div><div class="card flat">${ui.table([{ h: 'ID', f: c => c.id }, { h: 'Change', f: c => c.title }, { h: 'Risk', f: c => ui.sev(c.risk) }, { h: 'Approval gates', f: c => h`${ui.badge('peer review', c.gates.peer ? 'ok' : 'warn')} ${ui.badge('policy check', 'ok')} ${ui.badge('CAB', c.gates.cab ? 'ok' : 'mut')}` }, { h: 'Status', f: c => ui.badge(c.status, c.status === 'approved' ? 'ok' : c.status === 'rejected' ? 'bad' : 'warn') }, { h: '', f: c => c.status === 'pending' ? h`<div class="row">${ui.btn('Approve', 'ch.dec', c.id + ':approved', { s: 1, p: 1, w: 1 })}${ui.btn('Reject', 'ch.dec', c.id + ':rejected', { s: 1, d: 1, w: 1 })}</div>` : '' }], chg)}</div><p class="mut">Infra changes (IaC apply / Configurator) are gated on an approved change in the real build.</p>`;
    else if (t === 'cal') { const days = Array.from({ length: 30 }, (_, i) => i + 1); const clash = d => chg.filter(c => c.day === d && c.status !== 'rejected').length > 1; body = h`<div class="card"><h2>October 2026 – change calendar</h2><div class="cal">${['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(d => h`<div class="h">${d}</div>`)}${Array(3).fill(0).map(() => h`<div></div>`)}${days.map(d => h`<div class="d"><b>${d}</b>${chg.filter(c => c.day === d && c.status !== 'rejected').map(c => h`<span class="ev ${clash(d) ? 'hi' : ''}" title="${c.title}">${c.id}</span>`)}</div>`)}</div><p class="mut">Red = two changes on the same day (conflict).</p></div>`; }
    else if (t === 'sla') body = h`<div class="card flat">${ui.table([{ h: 'Service', f: s => s.svc }, { h: 'Tenant', f: s => s.tenant }, { h: 'SLA target', num: 1, f: s => s.target + '%' }, { h: 'Actual (30d)', num: 1, f: s => s.actual + '%' }, { h: 'Status', f: s => s.actual >= s.target ? ui.badge('met', 'ok') : ui.badge('BREACH', 'bad') }], COC.byTenant(D.sla))}</div>`;
    else body = h`<div class="grid g3">${D.integrations.map(i => h`<div class="card"><h2>${i.icon} ${i.name} ${ui.sw(i.on, 'in.int', i.name)}</h2><p class="mut">${i.desc}</p>${i.on ? ui.badge('connected', 'ok') : ui.badge('disabled', 'mut')}</div>`)}</div>`;
    return h`<div class="ph"><div class="grow"><h1>Incident &amp; Change Management</h1><p class="sub">Incident lifecycle, change approvals with gates, change calendar, SLA tracking, ServiceNow / Jira / PagerDuty.</p></div></div>
      <div class="grid g4">${ui.kpi('Open incidents', inc.filter(i => i.stage < 2).length, '', 'bad')}${ui.kpi('Pending changes', chg.filter(c => c.status === 'pending').length)}${ui.kpi('SLA breaches', COC.byTenant(D.sla).filter(s => s.actual < s.target).length, '', 'bad')}${ui.kpi('MTTR (30d)', '47 min', '−12% vs prior', 'good')}</div>
      ${ui.tabs('incidents', [['inc', 'Incidents'], ['chg', 'Change requests'], ['cal', 'Change calendar'], ['sla', 'SLA tracking'], ['int', 'Integrations']], t)}${body}`;
  } });

  /* ================= OBSERVABILITY ================= */
  const OB = { q: '', lv: 'All', svc: 'All', trace: null };
  COC.actions['ob.q'] = v => { OB.q = v; COC.refresh(); };
  COC.actions['ob.f'] = (v, el) => { OB[el.dataset.arg] = v; COC.refresh(); };
  COC.actions['ob.trace'] = id => { OB.trace = OB.trace === id ? null : id; COC.refresh(); };
  COC.actions['ob.la'] = a => { const [q, on] = a.split('|'); D.logAlerts.find(x => x.q === q).on = on === 'true'; COC.audit('Log alert toggled', q); COC.refresh(); };
  COC.register({ id: 'observability', name: 'Observability (logs/traces)', icon: '🔭', phase: 3, roles: ALL, render() {
    const t = COC.tabs.observability || 'map';
    let body;
    if (t === 'map') {
      const S = Object.fromEntries(D.svcs.map(s => [s.id, s]));
      body = h`<div class="card"><h2>Service dependency map</h2><svg viewBox="0 0 780 360" width="100%" role="img" aria-label="service map"><defs><marker id="ar" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 z" fill="#8892a6"/></marker></defs>
        ${raw(D.edges.map(([a, b]) => { const ax = S[a].x + 40, ay = S[a].y + 18, bx = S[b].x + 40, by = S[b].y + 18, dx = bx - ax, dy = by - ay, k = Math.min(dx ? 44 / Math.abs(dx) : 9, dy ? 22 / Math.abs(dy) : 9); return `<line x1="${ax + dx * k}" y1="${ay + dy * k}" x2="${bx - dx * k}" y2="${by - dy * k}" stroke="#8892a6" stroke-width="1.5" marker-end="url(#ar)"/>`; }).join(''))}
        ${raw(D.svcs.map(s => { const bad = s.err > 3 || s.p95 > 1000; return `<g><rect x="${s.x}" y="${s.y}" width="80" height="36" rx="8" fill="var(--panel2)" stroke="${bad ? 'var(--bad)' : 'var(--ok)'}" stroke-width="2"/><text x="${s.x + 40}" y="${s.y + 15}" text-anchor="middle" style="fill:var(--text);font-size:11px;font-weight:600">${COC.esc(s.id)}</text><text x="${s.x + 40}" y="${s.y + 28}" text-anchor="middle">${s.rate} rps · ${s.err}%</text></g>`; }).join(''))}</svg><p class="mut">Red outline = high errors or latency. Edges show "what calls what" across clusters.</p></div>`;
    } else if (t === 'red') body = h`<div class="card flat">${ui.table([{ h: 'Service', f: s => s.id }, { h: 'Rate (rps)', num: 1, f: s => s.rate }, { h: 'Errors', num: 1, f: s => ui.badge(s.err + '%', s.err > 3 ? 'bad' : s.err > 1 ? 'warn' : 'ok') }, { h: 'Duration p95', num: 1, f: s => s.p95 + ' ms' }, { h: 'Trend', f: s => chart.spark(s.spark, s.err > 3 ? 'var(--bad)' : 'var(--acc)') }], D.svcs)}</div>`;
    else if (t === 'trace') { const tr = D.traces.find(x => x.id === OB.trace); body = h`<div class="card flat">${ui.table([{ h: 'Trace', f: x => x.id }, { h: 'Operation', f: x => x.op }, { h: 'Entry service', f: x => x.svc }, { h: 'Duration', num: 1, f: x => ui.badge(x.ms + ' ms', x.ms > 1500 ? 'bad' : x.ms > 400 ? 'warn' : 'ok') }], D.traces, { click: 'ob.trace', key: x => x.id })}</div>${tr ? h`<div class="card"><h2>Waterfall – ${tr.op}</h2>${[['api-gateway', 0, .08], ['auth', .04, .1], [tr.svc, .12, .55], ['postgres', .2, .35], ['redis', .56, .06], ['kafka', .64, .08]].map(([s, a, w], i) => h`<div class="row" style="margin:4px 0"><span style="width:100px" class="mut">${s}</span><div style="flex:1;position:relative;height:16px;background:var(--panel2);border-radius:3px"><div style="position:absolute;left:${a * 100}%;width:${w * 100}%;height:100%;background:${COC.palette[i % 8]};border-radius:3px"></div></div><span class="mut" style="width:60px;text-align:right">${Math.round(tr.ms * w)} ms</span></div>`)}</div>` : h`<p class="mut">Click a trace to see its waterfall.</p>`}`; }
    else if (t === 'logs') {
      let ls = D.logs.filter(l => (OB.lv === 'All' || l.lv === OB.lv) && (OB.svc === 'All' || l.svc === OB.svc) && (!OB.q || (l.msg + l.svc).toLowerCase().includes(OB.q.toLowerCase())));
      body = h`<div class="row" style="margin-bottom:10px"><input id="ob-q" data-inp="ob.q" placeholder="Search logs across all clouds…" value="${OB.q}" style="width:300px">${ui.select('ob-lv', ['All', 'ERROR', 'WARN', 'INFO'], OB.lv, 'ob.f', 'lv')}${ui.select('ob-svc', ['All', ...D.svcs.map(s => s.id)], OB.svc, 'ob.f', 'svc')}<span class="mut">${ls.length} lines</span></div><div class="log">${ls.slice(0, 120).map(l => h`<div><span class="mut">${l.t}</span> <span class="${l.lv === 'ERROR' ? 'e' : l.lv === 'WARN' ? 'w' : 'i'}">${l.lv.padEnd(5)}</span> [${l.cloud}/${l.svc}] ${l.msg}</div>`)}</div>`;
    } else body = h`<div class="card flat">${ui.table([{ h: 'On', f: a => ui.sw(a.on, 'ob.la', a.q) }, { h: 'Log query', f: a => h`<code>${a.q}</code>` }, { h: 'Threshold', f: a => a.thr }], D.logAlerts)}</div>`;
    return h`<div class="ph"><div class="grow"><h1>Observability</h1><p class="sub">Service map, RED metrics, distributed traces, centralized logs and log-based alerting.</p></div></div>
      ${ui.tabs('observability', [['map', 'Service map'], ['red', 'RED metrics'], ['trace', 'Traces'], ['logs', 'Logs'], ['la', 'Log alerts']], t)}${body}`;
  } });
})();
